// Helper to convert concise raw tuples into the engine's standard question objects
function buildQuestions(raw) {
  return raw.map(([prompt, subprompt, options, answer, explanation]) => ({
    prompt,
    subprompt,
    options,
    answer,
    explanation
  }));
}

